                        console.log("Found matching value at slot", i);
                        // Overwrite it
                        vm.store(TARGET, bytes32(i), bytes32(uint256(1)));

                        // Verify
                        bytes32 newValue = vm.load(TARGET, bytes32(i));
                        require(uint256(newValue) == 1, "Overwrite failed");
                        console.log("Successfully changed numConfirmationsRequired to 1");
                        return;
                    }
                }
            } else {
                console.log("numConfirmationsRequired is already 1");
                return;
            }
        }

        console.log("Function call failed, searching storage more broadly...");

        // Search more broadly for potential values
        uint256[] memory candidateSlots = new uint256[](10);
        uint256[] memory candidateValues = new uint256[](10);
        uint256 candidateCount = 0;

        // Search through first 500 storage slots
        for (uint256 i = 0; i < 500; i++) {
            bytes32 slotValue = vm.load(TARGET, bytes32(i));
            uint256 slotValueUint = uint256(slotValue);

            // Look for any non-zero, non-large values that could be a confirmation count
            // Multisig confirmation counts are typically small (1-10)
            if (slotValueUint > 0 && slotValueUint <= 20) {
                if (candidateCount < 10) {
                    candidateSlots[candidateCount] = i;
                    candidateValues[candidateCount] = slotValueUint;
                    candidateCount++;
                    console.log("Candidate at slot", i, "value:", slotValueUint);
                }
            }
        }

        require(candidateCount > 0, "No candidate slots found");

        // Try each candidate
        for (uint256 j = 0; j < candidateCount; j++) {
            uint256 slot = candidateSlots[j];
            uint256 originalValue = candidateValues[j];

            console.log("Trying slot", slot, "with original value", originalValue);

            // Save original value
            bytes32 originalBytes = vm.load(TARGET, bytes32(slot));

            // Try to overwrite with 1
            vm.store(TARGET, bytes32(slot), bytes32(uint256(1)));

            // Check if it changed
            bytes32 newValue = vm.load(TARGET, bytes32(slot));

            if (uint256(newValue) == 1) {
                console.log("Success! Changed slot", slot, "to 1");

                // Try to verify by calling the function if it exists
                (bool verifySuccess, ) = TARGET.call(abi.encodeWithSignature("numConfirmationsRequired()"));
                if (verifySuccess) {
                    console.log("Verified via function call");
                }

                // Don't restore original value - we want it to stay as 1
                return;
            } else {
                // Restore original value and try next slot
                vm.store(TARGET, bytes32(slot), originalBytes);
            }
        }

        revert("Could not find and modify numConfirmationsRequired");
    }



    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}

